def verify(witness):
    core_gaps = witness['core_gaps']
    if not isinstance(core_gaps, list):
        raise ValueError('core_gaps must be a list')
    if len(core_gaps) != 18:
        raise ValueError('core_gaps must have length 18')
    counts = {1: 0, 2: 0, 3: 0}
    for g in core_gaps:
        if g not in (1, 2, 3):
            raise ValueError('gap outside finite core d in {1,2,3}')
        counts[g] += 1
    if counts[1] != 10:
        raise ValueError('count of 1-gaps must be 10')
    if counts[2] != 5:
        raise ValueError('count of 2-gaps must be 5')
    if counts[3] != 3:
        raise ValueError('count of 3-gaps must be 3')
    total = counts[1] + counts[2] + counts[3]
    if total != 18:
        raise ValueError('conservation total must be 18')
    weighted = counts[1] * 1 + counts[2] * 2 + counts[3] * 3
    if weighted != 29:
        raise ValueError('weighted sum must be 29')
    if weighted != 30 - 1:
        raise ValueError('conservation identity 29 = 30 - 1 violated')
    return True
